def lesson_id(case):
    return 'skill-example-' + case['slug'] + '-v1'


def source(case, paragraph):
    body = case['paragraphs'][paragraph - 1]
    return dict(kind='original-fictional-example', lesson_id=lesson_id(case),
                edition=1, paragraph=paragraph, text=body,
                sha256=hashlib.sha256(body.encode()).hexdigest())


def candidate_form(case):
    items = []
    for number, (prompt, choices, answer, paragraph) in enumerate(case['questions'], 1):
        items.append(dict(id=f'q{number}', objective_id=case['objective'], type='scenario',
                          lineage_id=f"original-{case['slug']}-observation-{number}-v1",
                          prompt=prompt, choices=[dict(id=str(i), text=text) for i, text in enumerate(choices)],
                          answer=str(answer), critical=True,
                          rationale=choices[answer] + '. Основание: ' + case['paragraphs'][paragraph - 1],
                          source=source(case, paragraph)))
    return dict(items=items, title=case['title'],
                scope='Проверяется понимание на учебном случае; практическое выполнение не сертифицируется.')


def install_examples(db):
    """Add content and a graph edition atomically; never rewrite existing evidence."""
    active = db.execute('SELECT r.body FROM skill_active a JOIN skill_releases r ON r.id=a.release_id WHERE singleton=1').fetchone()
    if not active:
        raise ValueError('Run init-skills first')
    current = json.loads(active[0])
    if current['release'] == RELEASE:
        return False
    if current['release'] != 'tree-2026-10-v1':
        raise ValueError('Examples require explicit rebase onto this graph; refusing to replace a newer release')
    tree = copy.deepcopy(current)
    tree['release'] = RELEASE
    nodes = {node['id']: node for node in tree['nodes']}
    db.execute('''INSERT INTO courses(id,title,description,outcome,goal,level,tools,prerequisites,author,updated_at,status)
        VALUES(?,?,?,?,?,?,?,?,?,?,?)''', (COURSE, 'Мастерская проверяемых решений', LABEL,
        'Разобрать семь учебных ситуаций: источники, приложения, код, тексты, команда, процесс и инструмент агента.',
        'essentials', 'Начальный', 'Текст урока; внешние AI-сервисы и оплата не нужны.',
        'Можно начать с любой темы.', 'AI Room · оригинальные учебные примеры', '2026-10-02', 'published'))
    db.execute('INSERT INTO modules VALUES(?,?,?,?)', (COURSE+'-cases', COURSE, 'Независимые учебные случаи', 0))
    for position, case in enumerate(CASES):
        db.execute('''INSERT INTO lessons(id,module_id,title,objective,body,minutes,position,access,task,checklist,status)
            VALUES(?,?,?,?,?,?,?,?,?,?,?)''', (lesson_id(case), COURSE+'-cases', case['title'],
            nodes[case['objective']]['title'], '\n\n'.join([f'Источник · абзац {i+1}\n{p}' for i,p in enumerate(case['paragraphs'])] + [LABEL]),
            7, position, 'free', case['task'], '\n'.join(case['checks']), 'published'))
        tree['mappings'].append(dict(objective_id=case['objective'], lesson_id=lesson_id(case),
                                     role='teaches', source={k:v for k,v in source(case, 1).items() if k != 'text'}))
    db.execute('INSERT INTO skill_releases(id,body) VALUES(?,?)', (RELEASE, json.dumps(tree, ensure_ascii=False)))
    db.execute('UPDATE skill_active SET release_id=? WHERE singleton=1', (RELEASE,))
    return True


def review_examples(db, reviewer):
    """Explicit operator review boundary, never invoked by seed/install."""
    from .skills import publish_reviewed_form
    active = db.execute('SELECT release_id FROM skill_active WHERE singleton=1').fetchone()
    if not active or active[0] != RELEASE:
        raise ValueError('Install examples and review the active example release first')
    user = db.execute('SELECT role FROM users WHERE id=?', (reviewer,)).fetchone()
    if not user or user[0] not in ('admin', 'editor'):
        raise ValueError('Editor review required')
    tree = json.loads(db.execute('SELECT body FROM skill_releases WHERE id=?', (RELEASE,)).fetchone()[0])
    for case in CASES:
        identity = 'skill-example-form-' + case['slug'] + '-v1'
        if not db.execute('SELECT 1 FROM skill_forms WHERE id=?', (identity,)).fetchone():
            publish_reviewed_form(db, id=identity, graph=tree, node_id=case['objective'],
                                  form=candidate_form(case), access='free', reviewer=reviewer)
